import subprocess, os
EXE=os.path.abspath("./executable")
def sym(s):
    p=subprocess.run([EXE,"--symbols"], input=s+"\n", capture_output=True, text=True, timeout=5)
    return p.stdout.strip()
def inv(s):
    p=subprocess.run([EXE,"--symbols","--invert"], input=s+"\n", capture_output=True, text=True, timeout=5)
    return p.stdout.strip()

# test words
for w in ["alpha","beta","gamma","pi","Alpha","ALPHA","(c)","(C)","(r)","(tm)","TM","(TM)","1/2","1/4","3/4","1/3","2/3","+/-","+-","<3",":)",":-)",":(",":D","o_o","^^","...", "``", "''", '""', "<<", ">>", "``hello''", "\"hello\"", "'hello'", "a/b", "a*b", "x^2", "H2O", "CO2", "E=mc^2", "a_b", "a|b", "a&b", "a#b", "a%b", "a@b", "a?b", "a~b", "a^b", "a`b", "a'b", 'a"b']:
    out=sym(w)
    if out!=w:
        print(f"{repr(w)} -> {repr(out)}")
print("--- invert extra ---")
# test invert for all unicode that might map? try common unicode symbols
candidates = ["≠","→","⇒","←","≤","≥","–","—","↔","⟶","⟵","…","«","»","©","®","™","±","×","÷","α","β","γ","π","Ω","∞","≈","≡","∧","∨","¬","∩","∪","∑","√","∂","∫","°","§","¶","·","•","↑","↓","↔","⇒","⇐","⇔","∀","∃","∈","×","÷"]
