fn parse_go_value(s: &str) -> Result<String, String> {
    // Valid base values
    let bases = ["comments","strings","imports","expression","type-def","type-alias","struct","interface","const","var","func","method","free-func","init-func","type-params","defer","select","go","switch","labeled","goto","struct-tags"];
    if bases.contains(&s) {
        return Ok(s.to_string());
    }
    // Check for ~ pattern: struct~PAT, interface~PAT, func~PAT
    for prefix in ["struct~","interface~","func~"] {
        if let Some(pat) = s.strip_prefix(prefix) {
            // Validate regex
            match fancy_regex::Regex::new(pat) {
                Ok(_) => return Ok(s.to_string()),
                Err(e) => {
                    // Need to produce error like: "invalid value '[invalid' for 'struct'\n\n  tip: error was: regex parse error:\n    [invalid\n    ^\nerror: unclosed character class"
                    // The clap error for invalid value with custom parser: return Err(String) will be shown as?
                    // For our test, original error for struct~[invalid was:
                    // "error: invalid value '[invalid' for 'struct'\n\n  tip: error was: regex parse error:\n    [invalid\n    ^\nerror: unclosed character class"
                    // We need to replicate. fancy_regex error Display is "Parsing error at position X: ..." or "regex parse error:..."?
                    // Let's check what fancy_regex error looks like for [invalid.
                    // Earlier we saw fancy_regex error for [invalid is "Parsing error at position 8: Invalid character class"
                    // But the tip shows "regex parse error:\n    [invalid\n    ^\nerror: unclosed character class"
                    // That's from `regex` crate? Hmm.
                    // For now, return generic.
                    return Err(format!("regex parse error:\n    {}\n    ^\nerror: {}", pat, e));
                }
            }
        }
    }
    // Also handle struct~<PATTERN> literal? No, that's just help template, not actual value.
    Err(format!("invalid value"))
}

