fn process_actions_with_lang_stdin(matches: &clap::ArgMatches, scope: &str, literal: bool, replacement: Option<String>, upper: bool, lower: bool, titlecase: bool, normalize: bool, german: bool, german_naive: bool, german_prefer: bool, symbols: bool, delete: bool, squeeze: bool, invert: bool, fail_any: bool, fail_none: bool, line_numbers: bool, only_matching: bool, input: &str) -> Result<()> {
    // Similar to search, but with actions: find lang ranges, then regex matches within, then apply actions to each regex match, then output modified content (or with prefixes if flags).
    let (lang_opt, prepared, custom) = get_lang_and_scopes(matches)?;
    let lang = lang_opt.ok_or_else(|| anyhow::anyhow!("No language"))?;
    let join = matches.get_flag("join-language-scopes");
    let lang_ranges = if let Some(q) = custom {
        find_custom_query_ranges(&lang, &q, input)?
    } else {
        if prepared.is_empty() { vec![] }
        else if prepared.len() == 1 { find_lang_ranges(&lang, &prepared[0], input)? }
        else {
            if join {
                let mut all = Vec::new();
                for sc in &prepared { all.extend(find_lang_ranges(&lang, sc, input)?); }
                all.sort(); all.dedup();
                all
            } else {
                let mut current = find_lang_ranges(&lang, &prepared[0], input)?;
                for sc in &prepared[1..] {
                    let mut next = Vec::new();
                    for (ps, pe) in current {
                        let substr = &input[ps..pe];
                        let sub_ranges = find_lang_ranges(&lang, sc, substr)?;
                        for (ss, se) in sub_ranges { next.push((ps+ss, ps+se)); }
                    }
                    current = next;
                    if current.is_empty() { break; }
                }
                current
            }
        }
    };
    // Within each lang range, find regex matches (with captures for replacement)
    let mut all_regex_matches: Vec<(usize, usize, RegexMatch)> = Vec::new();
    for (ls, le) in lang_ranges {
        let substr = &input[ls..le];
        let sub_matches = find_regex_matches(substr, scope, literal)?;
        for (ss, se, m) in sub_matches {
            // Adjust m's start/end to absolute? m.start/end are relative to substr (0..). Need absolute for later output building? For replacement, need captures (which are relative? Actually captures text is same, start/end relative? For output building, we need absolute ranges. Good. Create new RegexMatch with absolute start/end but same text/captures (captures text same, but start/end in captures? Our RegexMatch stores start/end absolute? Actually find_regex_matches returns (s,e,m) where s,e are relative to substr (since substr is input to that function). For absolute, add ls. For m's internal start/end (in RegexMatch struct), they are also relative (since built from substr). Need to adjust? For replacement, we only need text/captures (not positions), so fine. For output building, we use (s,e) absolute (ls+ss, ls+se). Good.
            let abs_s = ls + ss;
            let abs_e = ls + se;
            // Clone m with absolute? Actually m.text is same, numbered/named same. Good. Create new with absolute start/end.
            let new_m = RegexMatch { start: abs_s, end: abs_e, text: m.text.clone(), numbered: m.numbered.clone(), named: m.named.clone() };
            all_regex_matches.push((abs_s, abs_e, new_m));
        }
    }
    // Sort and dedup? For join overlapping, may have duplicates. Dedup by (s,e)? Good.
    all_regex_matches.sort_by(|a,b| a.0.cmp(&b.0).then(a.1.cmp(&b.1)));
    // Dedup by (s,e) (ignore captures? If same range from different lang ranges, captures same? Since same substr and same regex, captures same. Good. Dedup.
    {
        let mut deduped: Vec<(usize, usize, RegexMatch)> = Vec::new();
        for (s,e,m) in all_regex_matches {
            if let Some((ls,le,_)) = deduped.last() {
                if *ls==s && *le==e { continue; }
            }
            deduped.push((s,e,m));
        }
        all_regex_matches = deduped;
    }
    // Handle squeeze (before other actions)
    if squeeze {
        all_regex_matches = squeeze_matches(all_regex_matches, input);
    }
    let found = !all_regex_matches.is_empty();
