            print!("{}", out_pref);
        } else {
            print!("{}", input);
        }
        return Ok(());
    }
    // Apply actions pipeline to each match
    let mut new_texts: Vec<String> = Vec::new();
    for (_,_,m) in &all_regex_matches {
