            let new_len = new_texts[i].len();
            let new_s = (*s as isize + delta) as usize;
            let new_e = new_s + new_len;
            new_ranges.push((new_s, new_e));
            delta += new_len as isize - old_len as isize;
        }
        let out_pref = format_output_with_new_ranges(&output, &new_ranges, "(stdin)", line_numbers, only_matching);
        print!("{}", out_pref);
    } else {
        print!("{}", output);
    }
    Ok(())
}

