fn find_actions_matches_for_file(matches: &clap::ArgMatches, scope: &str, literal: bool, content: &str, squeeze: bool) -> Result<Vec<(usize, usize, RegexMatch)>> {
    let has_lang = has_language(matches);
    let mut all_matches: Vec<(usize, usize, RegexMatch)> = Vec::new();
    if has_lang {
        let (lang_opt, prepared, custom) = get_lang_and_scopes(matches)?;
        let lang = lang_opt.ok_or_else(|| anyhow::anyhow!("No language"))?;
        let join = matches.get_flag("join-language-scopes");
        let lang_ranges = if let Some(q) = custom {
            find_custom_query_ranges(&lang, &q, content)?
        } else {
            if prepared.is_empty() { vec![] }
            else if prepared.len() == 1 { find_lang_ranges(&lang, &prepared[0], content)? }
            else {
                if join {
                    let mut all = Vec::new();
                    for sc in &prepared { all.extend(find_lang_ranges(&lang, sc, content)?); }
                    all.sort(); all.dedup();
                    all
                } else {
                    let mut current = find_lang_ranges(&lang, &prepared[0], content)?;
                    for sc in &prepared[1..] {
                        let mut next = Vec::new();
                        for (ps, pe) in current {
                            let substr = &content[ps..pe];
                            let sub_ranges = find_lang_ranges(&lang, sc, substr)?;
                            for (ss, se) in sub_ranges { next.push((ps+ss, ps+se)); }
                        }
                        current = next;
                        if current.is_empty() { break; }
                    }
                    current
                }
            }
        };
        for (ls, le) in lang_ranges {
            let substr = &content[ls..le];
            let sub_matches = find_regex_matches(substr, scope, literal)?;
            for (ss, se, m) in sub_matches {
                let abs_s = ls + ss;
                let abs_e = ls + se;
                let new_m = RegexMatch { start: abs_s, end: abs_e, text: m.text.clone(), numbered: m.numbered.clone(), named: m.named.clone() };
                all_matches.push((abs_s, abs_e, new_m));
            }
        }
        all_matches.sort_by(|a,b| a.0.cmp(&b.0).then(a.1.cmp(&b.1)));
        // Dedup
        {
            let mut deduped = Vec::new();
            for (s,e,m) in all_matches {
                if let Some((ls,le,_)) = deduped.last() {
                    if *ls==s && *le==e { continue; }
                }
                deduped.push((s,e,m));
            }
            all_matches = deduped;
        }
    } else {
        all_matches = find_regex_matches(content, scope, literal)?;
    }
    if squeeze {
        all_matches = squeeze_matches(all_matches, content);
    }
    Ok(all_matches)
}

